/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// </summary>
[DataContract]
class METABNValidationJobContract extends METSysOperationTaskDataContract
{
    METABNValidationJobMonths  months;
    guid                       topPickingProcessId;
    str                        packedQuery;

}

Method.Source:
/// <summary>
/// get/set the number of months.
/// </summary>
/// <param name = "_months">Months.</param>
/// <returns>Months.</returns>
[DataMember]
public METABNValidationJobMonths parmMonths(int _months = months)
{
    months = _months;
    return months;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Gets/set packed query.
/// </summary>
/// <param name = "_packedQuery">Packed query.</param>
/// <returns>Packed query.</returns>
[
    DataMemberAttribute,
    AifQueryTypeAttribute('_packedQuery', queryStr(METABNValidationJobContractQuery))
]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

    /// <summary>
    /// Provides thread count parameter
    /// </summary>
    /// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
    /// <returns>The thread count</returns>
    [DataMember, SysOperationControlVisibilityAttribute(false)]
    public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
    {
        threadCount = _threadCount;

        return threadCount;
    }

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

    /// <summary>
    /// Validates data contract.
    /// </summary>
    /// <returns>True, if validated; otherwise, false.</returns>
    public boolean validate()
    {
        boolean ret = true;

        if (threadCount <= 0)
        {
            ret = checkFailed("@MET:ABNValidationThreadCountWarning");
        }

        if (ret)
        {
            if (months < 0)
            {
                ret = checkFailed("@MET:MonthsLessThanZeroError");
            }
            else if (months == 0)
            {
                warning("@MET:ABNValidateJobNoFilterError");
            }
        }

        return ret;
    }

    /// <summary>
    /// Checks if query filter are assigned values or not.
    /// </summary>
    /// <returns>True, if values assigned to filters; othewise, false.</returns>
    public boolean checkQueryFilterValue()
    {
        Query                query;
        QueryBuildDataSource qbds;
        QueryBuildRange      qbr;
        int                  rangeCount;

        query = this.getQuery();
        qbds = query.dataSourceTable(tableNum(CustTable));
        rangeCount = qbds.rangeCount();

        for (int i = 1 ; i <= rangeCount; i++)
        {
            qbr = qbds.range(i);

            if (qbr.value() != '')
            {
                return true;
            }
        }

        return false;
    }
